/**
 * @method
 * @name img_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_save_onclick = async function() {
    try {
        await scwin.insert();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF36001.img_save_onclick" });
    }
};

/**
 * @method
 * @name img_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF36001.img_close_onclick" });
    }
};

/**
 * @method
 * @name trs_haltschdl_OnSuccess
 * @description haltschdl On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_haltschdl_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 처리 되었습니다.");
        await $c.win.closePopup();
        // 부모창 reload 처리해야함
        $c.frame.path("../").fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF36001.trs_haltschdl_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_haltschdl_OnFail
 * @description haltschdl On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_haltschdl_OnFail = async function() {
    try {
        await $c.win.alert('trs_haltschdl.OnFail() :' + trs_haltschdl.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF36001.trs_haltschdl_OnFail" });
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    try {
        if (txb_isur_cd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF36001.txb_isur_cd_onblur" });
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF36001.img_com_srch_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name insert
 * @description insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    const vIsurCd = txb_isur_cd.getValue();
    if (vIsurCd.length !== 5) {
        await $c.win.alert("회사코드를 입력하세요.");
        txb_isur_cd.focus();
        return;
    }
    const vHaltschdlDd = edt_haltschdl_dd.getValue();
    if (vHaltschdlDd.length > 0 && vHaltschdlDd.length < 8) {
        await $c.win.alert("매매거래정지예정일을 올바르게 입력하시오.");
        edt_haltschdl_dd.focus();
        return;
    }
    const vReleasDd = edt_releas_dd.getValue();
    if (vReleasDd > 0 && vReleasDd.length < 8) {
        await $c.win.alert("매매거래해제예정일을 올바르게 입력하시오.");
        edt_releas_dd.focus();
        return;
    }
    const vNewschdlDd = edt_newschdl_dd.getValue();
    if (vNewschdlDd > 0 && vNewschdlDd.length < 8) {
        await $c.win.alert("신주권교부예정일을 올바르게 입력하시오.");
        edt_newschdl_dd.focus();
        return;
    }
    const vListschdlDd = edt_listschdl_dd.getValue();
    if (vListschdlDd > 0 && vListschdlDd.length < 8) {
        await $c.win.alert("상장예정일을 올바르게 입력하시오.");
        edt_listschdl_dd.focus();
        return;
    }
    dts_haltschdl.insertRow();
    dts_haltschdl.setCellData(1, "ISUR_CD", vIsurCd);
    dts_haltschdl.setCellData(1, "HALT_SCHDL_DD", vHaltschdlDd);
    dts_haltschdl.setCellData(1, "HALT_RELEAS_SCHDL_DD", vReleasDd);
    dts_haltschdl.setCellData(1, "NEWSTK_SCHDL_DD", vNewschdlDd);
    dts_haltschdl.setCellData(1, "LIST_SCHDL_DD", vListschdlDd);
    dts_haltschdl.setCellData(1, "REMK", txa_remk.getValue());
    // alert(dts_nfaith.text);

    const vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer === true) {
        // alert(dts_again.text);
        trs_haltschdl.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_haltschdl",
            action : "/TrdHaltSchdl.do",
            ref : "dts_haltschdl",
            target : "trs_haltschdl=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};
